INSERT INTO `tbl_literasi_soal` (`id`, `id_tugas`, `pertanyaan`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `jawaban_benar`, `id_sekolah`) VALUES
(1, 1, 'Kapan proklamasi kemerdekaan Indonesia dibacakan?', '17 Agustus 1945', '18 Agustus 1945', '1 Juni 1945', '10 November 1945', 'A', 1),
(2, 2, 'sadsrwer', 'ewrwer', 'erwer', 'ewrwer', 'ewrwer', 'A', 1),
(3, 3, 'Literasi bukan sekadar kemampuan membaca dan menulis. Lebih dari itu, literasi adalah kunci membuka jendela dunia, sebuah kemampuan untuk memahami, menganalisis, mengkritisi, dan menggunakan informasi guna memecahkan masalah dalam kehidupan sehari-hari. Menjadi literat berarti memiliki kekuatan untuk terus bertumbuh, berpikir merdeka, dan berkontribusi secara positif bagi masyarakat.', 'EQWEQWE', 'WEQWE', 'QWEQWE', 'WEQWE', 'A', 1),
(4, 4, 'ASDADASD', 'ADADA', 'ASDA', 'ASDAS', 'ASDASD', 'A', 1),
(5, 4, 'ADADA', 'ASDAS', 'ASDAS', 'ASDAS', 'ASDAS', 'A', 1);
INSERT INTO `tbl_literasi_tugas` (`id`, `id_sekolah`, `no_induk_guru`, `kelas`, `judul`, `deskripsi`, `tipe_media`, `file_media`, `durasi_minimal`, `batas_waktu`, `created_at`) VALUES
(1, 1, '197811182007012007', 'XII F 5', 'Sejarah Kemerdekaan Indonesia', 'Tontonlah dokumenter sejarah kemerdekaan Indonesia berikut ini hingga selesai.', 'video', 'https://www.youtube.com/watch?v=MhQ5678n_8w', 0, NULL, '2026-06-17 17:42:36'),
(2, 1, '197811182007012007', 'XII F 5', 'SEDANG PERBAIKAN', 'eeffsdf', 'video', 'https://youtu.be/uyyLot4PLXM?si=5s81SpFWR0kk9fgS', 180, NULL, '2026-06-17 17:59:13'),
(3, 1, '199408052022212011', 'X E 1', 'LITERASI 1', 'Literasi bukan sekadar kemampuan membaca dan menulis. Lebih dari itu, literasi adalah kunci membuka jendela dunia, sebuah kemampuan untuk memahami, menganalisis, mengkritisi, dan menggunakan informasi guna memecahkan masalah dalam kehidupan sehari-hari. Menjadi literat berarti memiliki kekuatan untuk terus bertumbuh, berpikir merdeka, dan berkontribusi secara positif bagi masyarakat.', 'video', 'https://youtu.be/_Jl3r-XrqTw?si=gtvUTcAqmXA56KkH', 180, NULL, '2026-06-18 14:11:08'),
(4, 1, '199408052022212011', 'X E 1', 'cerita unik', 'wa SdFGASGSV SDFWQEF', 'pdf', 'uploads/literasi/lit_1781794658_6a3407626aef5.pdf', 180, NULL, '2026-06-18 14:57:38');
